from __future__ import annotations

import json

import pytest

from llm_router import LLMRouter, Model, Provider, RouterProfile
from tests.llm_router.support.fault_server import ScriptedHTTPServer, ScriptedResponse
from tests.llm_router.support.workers.retry import (
    openai_chat_path,
    openai_success_response,
)
from tests.llm_router.support.workers.worker_patches import patched_openai_sdk

pytestmark = pytest.mark.verification_kind("unit")

_CHAT_PATH = openai_chat_path()

_EXPECTED = {"itemCount": 3, "userName": "ada"}

_SCHEMA = {
    "type": "object",
    "properties": {
        "itemCount": {"type": "integer"},
        "userName": {"type": "string"},
    },
    "required": ["itemCount", "userName"],
    "additionalProperties": False,
}


@pytest.mark.verifies("REQ_STRUCTURED_TEXT_OUTPUT[revision==2]")
def test_structured_object_returned_as_plain_mapping(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """The parsed public result is the plain JSON object the schema describes."""
    monkeypatch.setenv("OPENROUTER_API_KEY_1", "inventory-assurance-value")
    response_body = openai_success_response(text=json.dumps(_EXPECTED))
    with (
        ScriptedHTTPServer(
            port=0,
            routes={
                ("POST", _CHAT_PATH): [
                    ScriptedResponse(
                        status_code=200,
                        headers={"Content-Type": "application/json"},
                        body=response_body,
                    )
                ]
            },
        ) as server,
        patched_openai_sdk(
            forced_base_url=f"{server.base_url}/v1",
            disable_sdk_retries=True,
        ),
    ):
        router = LLMRouter(
            RouterProfile(model=Model.DEEPSEEK_V3, provider=Provider.OPENROUTER),
            temperature=0.0,
        )
        response = router.query("Describe the record.", response_schema=_SCHEMA)

    assert response.data["parsed"] == _EXPECTED
